INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('4061d14c-2c4c-4634-b561-41f42b1f76bc', 'Afoxolaner (NexGard)', 'afoxolaner (nexgard)', 'viên', 'Thận trọng ở thú có tiền sử động kinh hoặc co giật. Kiểm tra tuổi và cân nặng tối thiểu theo nhãn sản phẩm.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 280000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('fe8f7b01-04b5-4177-8391-032dc93f25f0', 'Aglepristone', 'aglepristone', 'lọ', 'Dùng cho chó cái. Không dùng khi cần giữ thai. Dùng kèm kháng sinh và theo dõi sát; trường hợp nặng vẫn cần phẫu thuật.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 450000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ae869ee7-f0fa-4e4f-9369-f3790eef327a', 'Allopurinol', 'allopurinol', 'viên', 'Thận trọng ở thú suy thận.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c8505441-2912-4bbb-aa2b-61b309642367', 'Amlodipine', 'amlodipine', 'viên', 'Theo dõi huyết áp định kỳ. Có thể làm nướu sưng nhẹ.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c29144c1-3b53-4cfb-978b-9104cb155e5a', 'Amoxicillin-Clavulanate', 'amoxicillin-clavulanate', 'viên', 'Không dùng cho thú có tiền sử dị ứng nhóm penicillin. Thận trọng ở thỏ, chuột lang, hamster vì có thể gây rối loạn hệ vi khuẩn ruột.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 12000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('50b9a41d-cf77-462c-91c6-cb669ec91b80', 'Amphotericin B', 'amphotericin b', 'lọ', 'Đường tiêm độc với thận. Dạng khí dung dùng theo chỉ định của bác sĩ.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 900000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('7273c23f-79ec-4586-9048-dcff4facde42', 'Ampicillin', 'ampicillin', 'lọ', 'Không dùng cho thú có tiền sử dị ứng nhóm penicillin. Thận trọng ở thỏ, chuột lang, hamster vì kháng sinh nhóm này có thể gây rối loạn hệ vi khuẩn ruột.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('98b57696-490a-450a-bef5-f17c8f689807', 'Apomorphine', 'apomorphine', 'ống', 'Chỉ dùng gây nôn cho chó, không dùng cho mèo. Không gây nôn khi thú lơ mơ, co giật hoặc đã nuốt chất ăn mòn (axit, kiềm), dầu hoả. Chỉ dùng theo chỉ định của bác sĩ.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 150000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('0f825ff6-ef1b-4e17-82d4-3414f51e30da', 'Atenolol', 'atenolol', 'viên', 'Thận trọng ở thú suy tim sung huyết hoặc suy thận. Không tự ngừng thuốc đột ngột.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('26140012-441b-4bc3-9363-7008612ebe24', 'Atropine (nhỏ mắt)', 'atropine (nho mat)', 'lọ', 'Làm giãn đồng tử, thú có thể sợ ánh sáng vài ngày. Không dùng khi thú bị tăng nhãn áp (glaucoma). Thuốc chảy xuống họng có thể làm chó chảy nhiều nước dãi.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 45000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f21f5a80-5a0c-4b45-96fe-bf508cebf33c', 'Azithromycin', 'azithromycin', 'viên', 'Thận trọng ở thú bệnh gan. Có thể gây nôn hoặc tiêu chảy.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('6ce69366-8343-4e9f-8172-350c56bd0756', 'Benazepril', 'benazepril', 'viên', 'Thận trọng ở thú suy thận hoặc mất nước: theo dõi chức năng thận và kali máu. Không dùng cho thú mang thai.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 12000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('21b702ea-af96-4957-9bf6-b056a0b7b959', 'Budesonide', 'budesonide', 'viên', 'Là corticoid: không tự ngừng đột ngột. Thận trọng khi dùng chung với thuốc kháng viêm NSAID.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e5e75da1-2df2-41ff-bcb2-7126e0f0dc08', 'Buprenorphine', 'buprenorphine', 'ml', 'Thuốc giảm đau nhóm opioid, có thể gây an thần. Thận trọng ở thú bệnh gan hoặc suy hô hấp.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 120000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ad067d94-d2cf-40c2-b880-b1b71373f019', 'Butorphanol', 'butorphanol', 'ml', 'Gây an thần. Thận trọng ở thú bệnh gan, bệnh thận, suy hô hấp và chấn thương đầu.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 90000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('17cd2115-2d10-4107-804a-e501785795e2', 'CaEDTA', 'caedta', 'ống', 'Phải dùng đúng loại calcium EDTA (CaEDTA), không dùng muối natri EDTA. Có thể gây độc thận: theo dõi chức năng thận.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 120000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('70578ab6-64e3-4258-a14b-c2d8b3f324df', 'Calcium gluconate', 'calcium gluconate', 'ống', 'Tiêm tĩnh mạch phải rất chậm và theo dõi nhịp tim vì có thể gây loạn nhịp. Thận trọng ở thú bệnh tim.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 20000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ad2a318d-80a9-4cce-aaca-5fbfa732d5a1', 'Canxi (đường uống)', 'canxi (duong uong)', 'viên', 'Chỉ dùng theo chỉ định của bác sĩ: thừa canxi gây hại cho thận và xương.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 2000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('a03217ee-4d6b-48d7-90b4-efcc7f28f391', 'Carnidazole', 'carnidazole', 'viên', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5903129d-8e22-4a0a-8bf4-f7abd712442c', 'Carprofen', 'carprofen', 'viên', 'Thuốc kháng viêm nhóm NSAID: không dùng chung với corticoid (như Prednisolone) hoặc NSAID khác. Dùng lâu dài cần theo dõi chức năng gan và thận, nhất là ở mèo. Thận trọng ở thú loét dạ dày.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('14d17039-2d00-4e5a-94bc-1bdb063887a0', 'Celecoxib', 'celecoxib', 'viên', 'Thuốc kháng viêm NSAID: không dùng chung với corticoid hoặc NSAID khác. Ngưng thuốc và báo bác sĩ nếu thú nôn, bỏ ăn hoặc phân đen.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f5e1fb5d-e840-4d81-aaf1-a1ac30112249', 'Cephalexin', 'cephalexin', 'viên', 'Thận trọng ở thú có tiền sử dị ứng kháng sinh nhóm cephalosporin hoặc penicillin. Nếu thú nôn khi uống thuốc lúc đói, cho uống cùng thức ăn.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('55756bf5-93c0-4c54-a3b0-cf3179af1092', 'Chloramphenicol (nhỏ mắt)', 'chloramphenicol (nho mat)', 'lọ', 'Dùng nhỏ mắt. Người cầm thuốc rửa tay sau khi dùng, phụ nữ mang thai nên tránh tiếp xúc. Không để đầu lọ chạm vào mắt.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ffcd1cc9-7981-45b3-b860-ef7ac1b5a288', 'Chlorhexidine', 'chlorhexidine', 'chai', 'Dùng ngoài da. Tránh vùng mắt, không để thú liếm hoặc nuốt.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 60000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ffb8c879-dc24-4870-83bb-4eb74c0d0d8b', 'Ciprofloxacin (nhỏ mắt)', 'ciprofloxacin (nho mat)', 'lọ', 'Dùng nhỏ mắt. Không để đầu lọ chạm vào mắt.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d6d07862-397b-4922-83d3-9cf3d8d36fe6', 'Cisapride', 'cisapride', 'viên', 'Không dùng khi nghi tắc nghẽn đường tiêu hoá.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 12000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('1777eb53-94bc-472c-93b1-fa95159eb70d', 'Clindamycin', 'clindamycin', 'viên', 'Không dùng cho thỏ, chuột lang, hamster (nguy cơ viêm ruột nặng). Có thể gây nôn, tiêu chảy.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c13e171e-1cce-42f5-bef2-ec953aaa32ed', 'Clomipramine', 'clomipramine', 'viên', 'Không dùng chung với Fluoxetine hoặc các thuốc ức chế MAO. Thận trọng ở thú có bệnh tim, có tiền sử co giật.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 20000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('8b281fb4-71b7-472b-8773-7f7582765cdd', 'Clopidogrel', 'clopidogrel', 'viên', 'Thuốc chống kết tập tiểu cầu: tăng nguy cơ chảy máu. Báo bác sĩ trước khi gây mê, phẫu thuật.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('2ec09289-8e1d-43ac-ae4f-30d35e43d685', 'Cyclophosphamide', 'cyclophosphamide', 'viên', 'Thuốc độc tế bào: chỉ bác sĩ chuyên khoa chỉ định, theo dõi xét nghiệm máu định kỳ. Người cầm thuốc phải đeo găng, không bẻ hoặc nghiền viên thuốc. Cho thú uống nhiều nước để giảm nguy cơ viêm bàng quang xuất huyết.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 40000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('8296eb20-ffcf-4fa2-a0e5-ca32d5bb0c77', 'Cyclosporine', 'cyclosporine', 'viên', 'Thuốc ức chế miễn dịch: chỉ bác sĩ chuyên khoa chỉ định, theo dõi xét nghiệm định kỳ. Không tự ngừng thuốc. Cho uống đều đặn một cách nhất quán (cùng hoặc cách bữa ăn).', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('62b5a929-1a42-4303-8cf2-2ed6a7fd5225', 'Cyclosporine (nhỏ mắt)', 'cyclosporine (nho mat)', 'tuýp', 'Thường phải dùng lâu dài, hiệu quả có thể chỉ rõ sau vài tuần. Dùng đều đặn theo chỉ định của bác sĩ.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 280000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b57ec58d-173f-49f2-9b0e-7970ccf99fb3', 'Dầu tắm Malaseb', 'dau tam malaseb', 'chai', 'Dùng ngoài da. Để dầu tắm trên da theo thời gian ghi trên nhãn rồi xả sạch. Tránh vùng mắt.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 320000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b5225016-510a-47ad-9eff-c0fc9db9a6bf', 'Deslorelin (Suprelorin)', 'deslorelin (suprelorin)', 'que', 'Que cấy dưới da. Tác dụng có thể kéo dài nhiều tháng; cấy theo chỉ định của bác sĩ.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 1800000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5ff0fe16-51fb-4da6-896a-adc3361279bd', 'Dextrose (glucose)', 'dextrose (glucose)', 'chai', 'Dung dịch đường ưu trương: truyền chậm theo chỉ định, thoát mạch gây hoại tử mô. Theo dõi đường huyết sau khi truyền.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 35000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5c8725fc-7112-44ba-bd37-fed36c55fcc1', 'Dịch truyền', 'dich truyen', 'chai', 'Truyền quá nhanh hay quá nhiều có thể gây quá tải dịch ở thú suy tim hoặc suy thận. Loại dịch và tốc độ truyền theo chỉ định của bác sĩ.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('19e65ddc-7edd-4b01-9b5e-17119766c7d0', 'Diminazene', 'diminazene', 'lọ', 'Khoảng liều an toàn hẹp: không vượt liều. Có thể gây độc thần kinh và tổn thương gan, nhất là ở chó.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 120000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('529f9f67-ae27-46b0-abd6-c4008c818afb', 'Diosmectite (Smecta)', 'diosmectite (smecta)', 'gói', 'Cho uống cách các thuốc khác ít nhất 2 giờ vì có thể làm giảm hấp thu thuốc.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e451bbe8-153a-4213-b296-3a0ebe09f9c3', 'DMSA (Succimer)', 'dmsa (succimer)', 'viên', 'Thuốc thải kim loại nặng dạng uống. Theo dõi chức năng gan, thận khi dùng.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 60000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('494acc5a-c41b-421f-8b4c-94ba3dd3cb7e', 'DOCP (Zycortal)', 'docp (zycortal)', 'ml', 'Thuốc tiêm thay thế hormone, tiêm cách nhau khoảng 25 ngày theo chỉ định. Theo dõi điện giải (natri, kali) định kỳ.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 350000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('433ed1c9-fa70-4a0b-b11d-73e4c2cd1ae1', 'Dorzolamide (nhỏ mắt)', 'dorzolamide (nho mat)', 'lọ', 'Dùng nhỏ mắt hạ nhãn áp. Có thể gây xót mắt thoáng qua.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 220000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('258efc19-bd62-4c23-abfe-921f552511bc', 'Doxorubicin', 'doxorubicin', 'lọ', 'Thuốc độc tế bào: chỉ bác sĩ chuyên khoa chỉ định, theo dõi xét nghiệm máu định kỳ. Người cầm thuốc phải đeo găng, không bẻ hoặc nghiền viên thuốc. Độc với tim, và với thận ở mèo. Thoát mạch gây hoại tử mô.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 900000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f2b7c6c5-7beb-4815-b6c8-3c73f3a3a81e', 'Doxycycline', 'doxycycline', 'viên', 'Không dùng cho thú mang thai và thú non đang mọc răng. Ở mèo nên cho uống kèm nước hoặc thức ăn vì viên có thể gây viêm, hẹp thực quản.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 6000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('94066bff-083d-4bb9-be89-7b1e79ee5175', 'Enrofloxacin', 'enrofloxacin', 'viên', 'Hạn chế dùng cho chó đang lớn vì ảnh hưởng sụn khớp. Ở mèo, liều cao có thể gây mù.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('eac92358-8f96-44c0-ac60-62a46af41b0c', 'Epi-Otic', 'epi-otic', 'chai', 'Dung dịch vệ sinh tai. Thận trọng khi màng nhĩ có thể đã thủng.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 180000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('aea2ff1b-4053-4848-a57e-06504522f615', 'Famciclovir', 'famciclovir', 'viên', 'Dùng cho mèo nhiễm Herpesvirus. Cần chỉnh liều ở mèo suy thận.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d32a5301-12cf-46c0-a7ae-f4a6fba0b69a', 'Famotidine', 'famotidine', 'viên', 'Thận trọng ở thú suy thận: có thể cần giảm liều.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('468d5141-d25b-4418-b243-93bbaa77a703', 'Feliway (pheromone)', 'feliway (pheromone)', 'chai', 'Dạng khuếch tán trong phòng hoặc xịt, không phải thuốc uống. Hiệu quả cần dùng liên tục vài tuần.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 450000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('dc336d79-8ae2-4345-a059-912979a9ccbe', 'Fenbendazole', 'fenbendazole', 'gói', 'Thận trọng ở chim đang thay lông và một số loài nhạy cảm (cò, diệc, bồ câu).', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d0c86fae-d13e-4462-babe-eab32a06fc0b', 'Fluconazole', 'fluconazole', 'viên', 'Thận trọng ở thú bệnh gan: theo dõi men gan khi dùng kéo dài.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e3b756b6-f147-4d64-9df0-0b6b8a7c4142', 'Fludrocortisone', 'fludrocortisone', 'viên', 'Theo dõi điện giải (natri, kali) và huyết áp. Không tự ngừng thuốc.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 20000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('0bd98cdb-6110-4738-a381-3571ff8473b1', 'Fluoxetine', 'fluoxetine', 'viên', 'Có thể mất vài tuần mới thấy hiệu quả. Không dùng chung với Clomipramine hoặc các thuốc ức chế MAO. Không tự ngừng đột ngột.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('3251e48a-02cd-4cff-b07b-e6cc29d00173', 'Fluralaner (Bravecto)', 'fluralaner (bravecto)', 'viên', 'Thận trọng ở thú có tiền sử động kinh hoặc co giật. Kiểm tra tuổi và cân nặng tối thiểu theo nhãn sản phẩm.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 450000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('bec4c965-ba39-4b9b-a580-425ff7842b5a', 'Fluticasone (xịt)', 'fluticasone (xit)', 'bình', 'Thuốc xịt hít cho mèo hen: dùng qua buồng hít chuyên dụng cho mèo.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 350000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e3f0200e-a294-404e-b1e6-dc8abe581a4a', 'Furosemide', 'furosemide', 'viên', 'Thuốc lợi tiểu: theo dõi nước, điện giải và chức năng thận. Để thú uống nước tự do.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 2000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('54bced3f-d9f0-4db4-8685-bc09de4914bd', 'Gabapentin', 'gabapentin', 'viên', 'Có thể gây buồn ngủ, loạng choạng. Cần giảm liều ở thú suy thận. Dạng dung dịch có thể chứa xylitol độc cho chó: kiểm tra thành phần.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('1c25322d-e080-42db-a3e0-2b8a15be1402', 'Gel Laxatone', 'gel laxatone', 'tuýp', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 120000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('4c367520-6563-43e7-bfd5-c2eb0d5a6adf', 'Glucosamine', 'glucosamine', 'viên', NULL, true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('855ff427-dc14-4e66-b763-d7843be4bf03', 'GS-441524', 'gs-441524', 'ml', 'Tình trạng pháp lý và nguồn thuốc khác nhau tùy nơi. Kiểm tra trước khi kê.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 450000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('87065f78-0eff-400c-9058-88f3a9d88095', 'Haloperidol', 'haloperidol', 'ml', 'Chỉ dùng cho chim khi bác sĩ chỉ định. Có thể gây an thần quá mức: theo dõi sát sau khi dùng.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 40000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c835a40f-2840-41b5-8825-5b5902ebb9cc', 'Imidocarb', 'imidocarb', 'ml', 'Có thể gây chảy nước dãi, nôn, tiêu chảy sau tiêm. Thận trọng ở thú bệnh gan, bệnh thận và thú đang dùng thuốc ức chế cholinesterase.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 80000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('3cd2046b-abaa-492d-9d6e-d38a1cf5c7dc', 'Insulin (Caninsulin)', 'insulin (caninsulin)', 'lọ', 'Nguy cơ hạ đường huyết: theo dõi đường huyết thường xuyên. Không tự đổi loại hay liều insulin khi chưa có chỉ định của bác sĩ.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 420000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('6b2b0c83-4c64-4d9f-9e46-e98afb6df671', 'Insulin Glargine', 'insulin glargine', 'lọ', 'Nguy cơ hạ đường huyết: theo dõi đường huyết thường xuyên. Không tự đổi loại hay liều insulin khi chưa có chỉ định của bác sĩ.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 550000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('04a5301a-035a-42da-a8d5-2975c9e8b3ae', 'Interferon omega (Virbagen Omega)', 'interferon omega (virbagen omega)', 'lọ', NULL, true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 1200000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('6b33654f-32ba-4e54-9483-731d2be7c825', 'Itraconazole', 'itraconazole', 'viên', 'Dễ gây độc cho vẹt xám châu Phi. Có thể gây độc gan: theo dõi men gan khi dùng kéo dài.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b5e49f35-cbf3-469a-98ac-8c4782c9bcdd', 'Ivermectin', 'ivermectin', 'ml', 'Không dùng cho chó giống Collie và chó chăn cừu: dễ nhạy cảm với thuốc (đột biến gen MDR1), có thể gây độc thần kinh.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c3028ba8-c17f-4143-bd06-29c9f6385ec8', 'Kali bromide', 'kali bromide', 'ml', 'Không tự ngừng thuốc đột ngột. Không dùng cho mèo vì có thể gây bệnh đường hô hấp. Giữ lượng muối trong khẩu phần ổn định.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e0b7810a-9836-42e1-a0fc-a069df3e7073', 'Ketoconazole', 'ketoconazole', 'viên', 'Có thể gây độc gan: theo dõi men gan khi dùng dài ngày. Thận trọng ở thú bệnh gan. Cho uống cùng thức ăn.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ab770404-fbef-492c-adb6-b0e3b3abc53e', 'Lactated Ringer', 'lactated ringer', 'chai', 'Dịch truyền tĩnh mạch. Thận trọng ở thú suy tim hoặc suy thận: truyền quá nhanh hay quá nhiều có thể gây quá tải dịch.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('0d24d418-5234-4433-9857-e5123ae50a41', 'Lactulose', 'lactulose', 'ml', 'Dùng quá liều gây tiêu chảy, đầy hơi. Cho thú uống đủ nước.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b7d00a89-a445-420a-b648-368ee77711ed', 'Latanoprost (nhỏ mắt)', 'latanoprost (nho mat)', 'lọ', 'Chủ yếu dùng cho chó. Không dùng khi thủy tinh thể bị lệch ra trước. Có thể làm co nhỏ đồng tử.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 280000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('838d9838-a909-4b57-916b-5d60fb5f0cb7', 'Leuprolide', 'leuprolide', 'ống', 'Thuốc tiêm, dùng theo chỉ định của bác sĩ.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 900000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f543254e-7bf5-4c6f-8b1f-f7878fdffdbc', 'Levetiracetam', 'levetiracetam', 'viên', 'Không tự ngừng thuốc đột ngột vì có thể gây co giật trở lại. Cần giảm liều ở thú suy thận.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 6000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('8abc0541-0573-47e9-bf5c-c6499a6312e6', 'Levothyroxine', 'levothyroxine', 'viên', 'Cần xét nghiệm nồng độ hormone tuyến giáp (T4) định kỳ để chỉnh liều. Thận trọng ở thú bệnh tim.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d3514c2b-fa3d-4af0-8453-6e7c99a20706', 'Lidocaine', 'lidocaine', 'ống', 'Thận trọng loạn nhịp tim. Mèo rất nhạy cảm với lidocaine: chỉ dùng theo chỉ định của bác sĩ.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('43cdef9f-0ed7-4a5f-8d5c-f7ce0a4be875', 'Lime sulfur', 'lime sulfur', 'chai', 'Dùng ngoài da. Phải pha đúng nồng độ, có mùi nặng và làm ố đồ vật. Ngăn thú liếm vì nuốt phải có thể gây nôn. Nấm có thể lây sang người: cần vệ sinh môi trường.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 150000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('45ada560-9992-4891-a900-19500217fbdc', 'Lokivetmab (Cytopoint)', 'lokivetmab (cytopoint)', 'lọ', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 1200000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('1ce204fc-5aee-474e-bc8a-4646bc8a74ba', 'Malt paste', 'malt paste', 'tuýp', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 130000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('086c89c3-082b-44ae-a7eb-132e1b847fb3', 'Maropitant (Cerenia)', 'maropitant (cerenia)', 'viên', 'Thận trọng ở thú non và thú bệnh gan. Kiểm tra độ tuổi tối thiểu theo nhãn sản phẩm.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 65000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e71070e1-3c81-4a5b-8003-0708d798c3f5', 'Melarsomine (Immiticide)', 'melarsomine (immiticide)', 'lọ', 'Chỉ dùng cho chó, không dùng cho mèo. Sau điều trị phải cho nghỉ ngơi nghiêm ngặt vì nguy cơ tắc mạch phổi do giun chết.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 2800000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('2ba6cbc4-4a2b-44ae-a4b0-81ba89fd8f77', 'Meloxicam', 'meloxicam', 'ml', 'Thuốc kháng viêm nhóm NSAID: không dùng chung với corticoid (như Prednisolone) hoặc NSAID khác. Dùng lâu dài cần theo dõi chức năng gan và thận, nhất là ở mèo. Thận trọng ở thú mất nước hoặc loét dạ dày.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 12000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('1d695d1b-d22d-4d12-9480-a6b77a1f4e03', 'Men vi sinh (FortiFlora)', 'men vi sinh (fortiflora)', 'gói', NULL, true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('32d669e4-feed-4b1c-b143-a40d31e42440', 'Methimazole', 'methimazole', 'viên', 'Cần theo dõi công thức máu, men gan và nồng độ T4 định kỳ. Có thể gây nôn, ngứa vùng mặt.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 6000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('9024506a-b041-4ebb-8e26-feb9224573b1', 'Methocarbamol', 'methocarbamol', 'viên', 'Có thể gây buồn ngủ, loạng choạng.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('2ce7530b-f601-48c7-88b3-872205d23e6e', 'Methylprednisolone acetate', 'methylprednisolone acetate', 'ống', 'Corticoid dạng tiêm tác dụng kéo dài. Không dùng chung với thuốc kháng viêm NSAID. Có thể làm tăng uống nước, đi tiểu nhiều.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 250000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('1289a366-04fa-4e4f-93b7-beb77429f2ca', 'Metoclopramide', 'metoclopramide', 'viên', 'Không dùng khi nghi tắc nghẽn đường tiêu hoá. Có thể gây bồn chồn, kích động.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 2000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('0b4c71f8-7feb-40bb-9715-bfc8ab7c1430', 'Metronidazole', 'metronidazole', 'viên', 'Liều cao hoặc dùng kéo dài có thể gây độc thần kinh (loạng choạng, run). Thận trọng ở thú bệnh gan và thú mang thai.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('9e4256c2-d891-4933-b671-44a257564840', 'Miconazole', 'miconazole', 'chai', 'Dầu tắm dùng ngoài da. Tránh vùng mắt và không để thú liếm. Nấm có thể lây sang người: cần vệ sinh môi trường.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 90000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('4fc6cd7a-1023-490b-a831-42848fa0f93b', 'Milbemycin', 'milbemycin', 'viên', 'Giống Collie có thể nhạy cảm khi dùng liều cao hơn liều phòng giun tim thông thường.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 80000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d6faf955-f07e-485b-a071-191eac1269ba', 'Mirtazapine', 'mirtazapine', 'viên', 'Dùng để kích thích ăn. Thận trọng ở thú bệnh gan, bệnh thận: có thể cần giảm liều.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5f3b1fc7-f7cf-4221-b072-7204a7ec62a1', 'Molnupiravir', 'molnupiravir', 'viên', 'Tình trạng pháp lý và nguồn thuốc khác nhau tùy nơi. Kiểm tra trước khi kê.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 40000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('3d694afa-27fe-4564-adb3-d128277c2eb6', 'Moxidectin (Advocate)', 'moxidectin (advocate)', 'tuýp', 'Dùng đúng loại dành cho chó hoặc cho mèo. Kiểm tra tuổi và cân nặng tối thiểu theo nhãn sản phẩm.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 220000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('28a78cf7-a9eb-40c4-973a-3096d2d36929', 'Mupirocin', 'mupirocin', 'tuýp', 'Dùng ngoài da. Không để thú liếm.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 60000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('387aa99d-92aa-4ede-b296-77133a4f9cb4', 'Mycophenolate', 'mycophenolate', 'viên', 'Thuốc ức chế miễn dịch: chỉ bác sĩ chuyên khoa chỉ định, theo dõi xét nghiệm máu định kỳ. Có thể gây rối loạn tiêu hoá.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 20000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('0bb00026-995b-4747-95f4-deae97f0abea', 'Nước mắt nhân tạo', 'nuoc mat nhan tao', 'lọ', NULL, true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 60000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('32fd9745-869a-4a7f-9c5f-a4e1ecde3cc1', 'Nước muối sinh lý 0,9%', 'nuoc muoi sinh ly 0,9%', 'chai', NULL, true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('696177bc-25bf-42ce-b790-dbb5eb62cca9', 'Nystatin', 'nystatin', 'ml', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('04359130-0011-43aa-91fd-27ef5e063245', 'Oclacitinib (Apoquel)', 'oclacitinib (apoquel)', 'viên', 'Không dùng cho chó dưới 12 tháng tuổi, chó mang thai hoặc đang cho con bú. Có thể làm tăng nguy cơ nhiễm trùng.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 45000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b9731d06-c78e-4168-85c1-4afc366bc264', 'Ofloxacin (nhỏ mắt)', 'ofloxacin (nho mat)', 'lọ', 'Dùng nhỏ mắt. Không để đầu lọ chạm vào mắt.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('eac45eb1-edac-4971-aaed-eb2dd98ba0ff', 'Omeprazole', 'omeprazole', 'viên', 'Cho uống lúc đói, trước bữa ăn khoảng 30 phút.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e60c127a-f711-4b88-a302-c8578e74b748', 'Osaterone (Ypozane)', 'osaterone (ypozane)', 'viên', 'Chỉ dùng cho chó đực. Người cầm thuốc rửa tay sau khi dùng; phụ nữ mang thai hoặc đang cho con bú nên tránh tiếp xúc.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 280000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5e668b64-fa45-4778-a8ba-ab5c25598a06', 'Otomax', 'otomax', 'tuýp', 'Thuốc nhỏ tai. Không dùng khi màng nhĩ thủng (nguy cơ độc với tai). Thận trọng ở thú mang thai.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 200000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f2767ab2-471f-4ff7-adbe-2bfc14cf0ddc', 'Oxytetracycline', 'oxytetracycline', 'tuýp', NULL, true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 35000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('57befe80-c1a3-443c-94e1-1c4418cfdf7d', 'Oxytetracycline (mỡ mắt)', 'oxytetracycline (mo mat)', 'tuýp', 'Dùng tra mắt. Không để đầu tuýp chạm vào mắt.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('71e98c4b-fad0-4545-83cc-345109dd1123', 'Oxytocin', 'oxytocin', 'ml', 'Chỉ dùng khi bác sĩ đã loại trừ tắc nghẽn đường sinh; dùng sai có thể gây vỡ tử cung.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('1e5157a8-9dfc-4ff5-8811-f0be4876e75a', 'Penicillin G', 'penicillin g', 'lọ', 'Không dùng cho thú có tiền sử dị ứng nhóm penicillin. Thận trọng ở thỏ, chuột lang, hamster vì có thể gây rối loạn hệ vi khuẩn ruột.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 20000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('4b9cff73-bce9-4ee4-9aef-4cce4ef69da6', 'Phenobarbital', 'phenobarbital', 'viên', 'Có thể gây buồn ngủ, loạng choạng lúc đầu. Thận trọng ở thú bệnh gan. Không ngừng đột ngột vì có thể gây co giật bùng phát.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 3000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('8fccfb48-3446-4602-9822-b65f6fdc27b7', 'Pimobendan', 'pimobendan', 'viên', 'Không dùng cho thú bị bệnh cơ tim phì đại hoặc bệnh gây cản trở dòng máu ra khỏi tim. Cho uống theo hướng dẫn trên nhãn sản phẩm.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('350c65d8-3d46-4440-a620-111fbef1cbff', 'Ponazuril', 'ponazuril', 'ml', 'Dùng theo chỉ định của bác sĩ; kiểm tra độ tuổi tối thiểu theo nhãn.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 40000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b8a45578-7dac-4b56-ba53-fc330918210f', 'Povidone-iodine', 'povidone-iodine', 'chai', 'Dùng ngoài da. Pha loãng theo hướng dẫn, tránh vùng mắt và không để thú liếm.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 40000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('14f596c3-ebdd-47ac-81ae-5cca1d5cd11c', 'Pradofloxacin', 'pradofloxacin', 'viên', 'Kháng sinh nhóm fluoroquinolone: hạn chế dùng cho thú đang lớn (ảnh hưởng sụn khớp) và thú mang thai.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 45000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c312a6b7-eb2f-4307-ba3b-e9c6641dc094', 'Praziquantel', 'praziquantel', 'viên', 'Kiểm tra tuổi và cân nặng tối thiểu theo nhãn sản phẩm.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5b74c69f-cebd-43b6-9378-c0b3beffe070', 'Prazosin', 'prazosin', 'viên', 'Có thể gây hạ huyết áp. Thận trọng ở thú suy thận hoặc đang dùng thuốc hạ áp. Mèo đực tắc tiểu là ca cấp cứu: thuốc không thay thế việc thông tiểu.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 6000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('4d657099-34ce-4503-a524-f085a71ab425', 'Prednisolone', 'prednisolone', 'viên', 'Không dùng khi đang nhiễm nấm hoặc loét dạ dày. Thận trọng ở thú tiểu đường, thú mang thai. Dùng kéo dài thì không ngừng đột ngột.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 2000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('c54e1e9a-f4cf-4d24-bb06-d34b15b4beca', 'Prednisolone acetate (nhỏ mắt)', 'prednisolone acetate (nho mat)', 'lọ', 'Corticoid nhỏ mắt: không dùng khi mắt đang có loét giác mạc. Không tự ngừng đột ngột nếu đã dùng dài ngày.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 120000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('83c21fa7-e698-48a5-9183-36011a3de79d', 'ProZinc', 'prozinc', 'lọ', 'Nguy cơ hạ đường huyết: theo dõi đường huyết thường xuyên. Không tự đổi loại hay liều insulin khi chưa có chỉ định của bác sĩ.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 600000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('249c49fb-9bbf-4834-b94c-1cc060988c29', 'Pyrantel', 'pyrantel', 'viên', 'Kiểm tra tuổi và cân nặng tối thiểu theo nhãn sản phẩm.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('dcf1aa48-0eb0-46c2-ba7f-9dc4734cb9ff', 'Remdesivir', 'remdesivir', 'lọ', 'Tình trạng pháp lý và nguồn thuốc khác nhau tùy nơi. Kiểm tra trước khi kê.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 1500000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('28bfbb9a-cfb8-4588-991e-e18fa08bb33a', 'Ronidazole', 'ronidazole', 'viên', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('fdcecf1f-88b1-4cb2-9043-bf73385fcca1', 'SAMe (S-adenosylmethionine)', 'same (s-adenosylmethionine)', 'viên', 'Thuốc bổ gan. Thường cho uống lúc đói, xa bữa ăn.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 25000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f3845282-33ec-4de7-8545-cd2bd1f2cf28', 'Selamectin (Revolution)', 'selamectin (revolution)', 'tuýp', 'Kiểm tra tuổi và cân nặng tối thiểu theo nhãn sản phẩm.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 150000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('386d3172-d262-4b03-95c0-c586730bdd98', 'Sildenafil', 'sildenafil', 'viên', 'Có thể gây hạ huyết áp, đỏ mặt. Thận trọng ở thú có bệnh tim.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 12000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('25a8bd7d-2a4e-4e7b-b954-a074df5e269c', 'Silver sulfadiazine', 'silver sulfadiazine', 'tuýp', 'Dùng ngoài da cho vết thương, vết bỏng. Không để thú liếm hoặc nuốt.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 40000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('fd620b0b-845c-406d-bf24-f0ea31c50598', 'Silymarin', 'silymarin', 'viên', 'Thuốc bổ gan.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 6000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('37cc69a9-cce6-452a-8f58-6cb7613b413e', 'Sucralfate', 'sucralfate', 'ml', 'Cho uống lúc đói. Cho uống cách các thuốc uống khác ít nhất 2 giờ vì làm giảm hấp thu thuốc.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 4000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('11b91a58-2027-401b-bd29-a49591b2006d', 'Sulfadimethoxine (Albon)', 'sulfadimethoxine (albon)', 'ml', 'Cho thú uống đủ nước. Thận trọng ở thú suy thận hoặc suy gan.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('5f5544e0-04e9-404f-bf6f-680c89ffdfa4', 'Surolan', 'surolan', 'chai', 'Thuốc nhỏ tai. Không dùng khi màng nhĩ thủng. Thận trọng ở thú mang thai.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 230000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('8063f9ae-aab3-4c35-9020-54eac7cf4f75', 'Tacrolimus (nhỏ mắt)', 'tacrolimus (nho mat)', 'lọ', 'Dùng nhỏ mắt, thường khi Cyclosporine không đủ hiệu quả. Dùng đều đặn theo chỉ định của bác sĩ.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 300000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('cba73968-188c-4106-83e6-0df2cec58f6d', 'Telmisartan (Semintra)', 'telmisartan (semintra)', 'ml', 'Thận trọng ở thú mất nước hoặc suy thận: theo dõi chức năng thận và huyết áp.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 45000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('096295e5-6b12-454c-9a2f-ed52196fec20', 'Terbinafine', 'terbinafine', 'viên', 'Theo dõi men gan khi dùng kéo dài.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 18000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('79739721-4d64-4d99-95cc-322893c7d93b', 'Terbutaline', 'terbutaline', 'viên', 'Thận trọng ở thú bệnh tim hoặc tăng huyết áp.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('95406100-0f55-4354-8693-91c4e8ba7513', 'Than hoạt tính', 'than hoat tinh', 'gói', 'Không dùng khi thú lơ mơ hoặc không nuốt được vì nguy cơ sặc vào phổi. Có thể gây táo bón, mất nước.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('3073e247-17e3-41af-966d-bde0acf5a1e6', 'Theophylline', 'theophylline', 'viên', 'Khoảng liều an toàn hẹp, quá liều gây tim nhanh, bồn chồn, co giật. Không tự tăng liều.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('ce215e12-e604-4431-8416-29a7da3b1c20', 'Timolol (nhỏ mắt)', 'timolol (nho mat)', 'lọ', 'Dùng nhỏ mắt hạ nhãn áp. Thận trọng ở thú có bệnh tim hoặc hen.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 90000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('b2f1983c-11e2-4cc9-a896-f4084d96aaa4', 'Tobramycin (nhỏ mắt)', 'tobramycin (nho mat)', 'lọ', 'Dùng nhỏ mắt. Không để đầu lọ chạm vào mắt.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 30000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d18ed737-26e8-4723-b600-c3a6645d4b47', 'Toceranib (Palladia)', 'toceranib (palladia)', 'viên', 'Thuốc độc tế bào: chỉ bác sĩ chuyên khoa chỉ định, theo dõi xét nghiệm máu định kỳ. Người cầm thuốc phải đeo găng, không bẻ hoặc nghiền viên thuốc.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 600000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('86783ffe-9a95-48e5-a64d-1f6a108ef394', 'Toltrazuril (Baycox)', 'toltrazuril (baycox)', 'chai', NULL, true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 180000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('4103aed7-a673-4d6e-aa8c-9c3d7b088dab', 'Trilostane (Vetoryl)', 'trilostane (vetoryl)', 'viên', 'Cần theo dõi cortisol (test ACTH) định kỳ. Không dùng cho thú mang thai, thú bệnh gan hoặc bệnh thận nặng.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 50000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('57cfe0a7-c300-4564-92af-6cc5d773854f', 'Trimethoprim-Sulfa', 'trimethoprim-sulfa', 'viên', 'Thận trọng ở thú bệnh gan, bệnh thận. Dùng kéo dài ở chó có thể gây khô mắt.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 5000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('e2910b78-6098-44a2-b773-c251a5f8796d', 'Tylosin', 'tylosin', 'gói', NULL, true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 15000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('7cae1082-f8e8-4950-94ed-0a023e03d383', 'Ursodiol', 'ursodiol', 'viên', 'Không dùng khi tắc ống mật hoàn toàn. Nên cho uống cùng thức ăn.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 20000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('6e738ce5-e699-40c8-8251-b44eac86ed2c', 'Vincristine', 'vincristine', 'lọ', 'Thuốc độc tế bào: chỉ bác sĩ chuyên khoa chỉ định, theo dõi xét nghiệm máu định kỳ. Người cầm thuốc phải đeo găng, không bẻ hoặc nghiền viên thuốc. Thoát mạch gây hoại tử mô.', true, '2026-11-13 10:33:53.619363+00', '2026-11-13 10:33:53.619363+00', 450000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('12769cf7-a4b5-4cd5-b993-9e2ba49b6f89', 'Vitamin A', 'vitamin a', 'ml', 'Thừa vitamin A gây ngộ độc: chỉ dùng đúng liều bác sĩ chỉ định.', true, '2026-11-11 17:26:21.798906+00', '2026-11-11 17:26:21.798906+00', 8000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('f84f46fb-0055-4fa6-b4d6-2aa257902014', 'Vitamin B12', 'vitamin b12', 'ml', NULL, true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 10000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('347b6387-4b17-4908-9049-1939765476bf', 'Vitamin D3', 'vitamin d3', 'ml', 'Thừa vitamin D3 gây ngộ độc (tăng canxi máu): chỉ dùng đúng liều bác sĩ chỉ định.', true, '2026-11-12 03:15:17.162379+00', '2026-11-12 03:15:17.162379+00', 12000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('8f810208-8db0-444f-9156-94b6e928f7c1', 'Voriconazole', 'voriconazole', 'viên', 'Ở mèo, liều cao có thể gây độc thần kinh và ảnh hưởng thị lực. Thận trọng ở thú bệnh gan, theo dõi men gan.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 150000.00);
INSERT INTO public.medications (id, name, search_name, unit, caution, active, created_at, updated_at, unit_price) VALUES ('d2ac5a8d-3b50-413e-bee5-7a6d85466487', 'Zidovudine (AZT)', 'zidovudine (azt)', 'viên', 'Có thể gây thiếu máu. Cần xét nghiệm máu định kỳ khi dùng.', true, '2026-11-10 15:53:16.753881+00', '2026-11-10 15:53:16.753881+00', 30000.00);
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('be0f24e8-a92d-4c2f-9a1e-90aa846536d2', 'Viêm da dị ứng - chó', 'viem da di ung - cho', 'Viêm da dị ứng ở chó: ngứa, đỏ da, gãi nhiều.', 'Giảm ngứa và viêm; tìm và hạn chế tác nhân gây dị ứng (thức ăn, bọ chét, môi trường).', 'Tái khám sau 7 ngày. Giữ da khô, sạch.', 'db3436f4-a077-4194-be88-badd15c64daa', '2026-11-10 16:38:05.233428+00', '2026-11-10 16:38:05.233428+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('906090f2-9af3-4fd9-ab90-805eb41292fe', 'Ghẻ Demodex - chó', 'ghe demodex - cho', 'Viêm da do ghẻ Demodex ở chó.', 'Diệt ký sinh trùng. Điều trị kéo dài đến khi cạo da soi kính âm tính.', 'Tái khám và cạo da kiểm tra định kỳ.', 'db3436f4-a077-4194-be88-badd15c64daa', '2026-11-10 16:38:05.256176+00', '2026-11-10 16:38:05.256176+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('26d9aaec-3fa0-4f2c-b5b7-5341d05f65d0', 'Viêm tai ngoài - chó', 'viem tai ngoai - cho', 'Viêm tai ngoài ở chó.', 'Vệ sinh ống tai rồi nhỏ thuốc theo phác đồ.', 'Tái khám sau 7-10 ngày. Không dùng thuốc nhỏ tai khi nghi màng nhĩ thủng.', 'db3436f4-a077-4194-be88-badd15c64daa', '2026-11-10 16:38:05.259365+00', '2026-11-10 16:38:05.259365+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('485fda91-65a7-42ad-b85b-f143aa2f8590', 'Nấm da - mèo', 'nam da - meo', 'Nấm da (Ringworm) ở mèo.', 'Thuốc uống kết hợp tắm thuốc ngoài da; vệ sinh môi trường.', 'Nấm có thể lây sang người: cách ly mèo bệnh và vệ sinh môi trường. Điều trị đến khi cấy nấm âm tính.', 'db3436f4-a077-4194-be88-badd15c64daa', '2026-11-10 16:38:05.262432+00', '2026-11-10 16:38:05.262432+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('5a69e5b4-a6f7-4354-9b99-a16bc1ffcd3d', 'Leptospirosis - chó', 'leptospirosis - cho', 'Leptospirosis ở chó: sốt, vàng da, tiểu ít, suy thận.', 'Kháng sinh diệt khuẩn, truyền dịch hỗ trợ thận; cách ly thú bệnh.', 'Bệnh lây sang người: vệ sinh kỹ khi chăm sóc. Tái khám theo dõi chức năng gan thận.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('28bff4a3-8c98-4564-a500-15b54a631bf8', 'Viêm gan truyền nhiễm (CAV-1) - chó', 'viem gan truyen nhiem (cav-1) - cho', 'Viêm gan truyền nhiễm (CAV-1) ở chó: sốt, đau bụng, giác mạc đục xanh.', 'Điều trị hỗ trợ: truyền dịch, kháng sinh chống bội nhiễm, thuốc bổ gan.', 'Bệnh do virus, điều trị chủ yếu là hỗ trợ. Tái khám theo dõi men gan.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('62003bd8-2324-44bb-8351-0cedb665bad5', 'Viêm tụy - chó', 'viem tuy - cho', 'Viêm tụy ở chó: nôn, đau bụng, bỏ ăn.', 'Chống nôn, giảm đau, truyền dịch; cho nhịn hoặc ăn lại thức ăn ít béo theo chỉ định.', 'Tái khám nếu nôn tái phát hoặc bỏ ăn quá 24 giờ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('784bd810-c362-49fe-b427-961a7755e8e3', 'Tiểu đường - chó', 'tieu duong - cho', 'Tiểu đường ở chó: uống nhiều, tiểu nhiều, sụt cân.', 'Tiêm insulin đều đặn kết hợp chế độ ăn ổn định.', 'Chủ nuôi cần học cách tiêm và nhận biết hạ đường huyết. Tái khám đo đường huyết định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('eee44f7d-5870-4b2e-9802-79a5ba584201', 'Suy giáp - chó', 'suy giap - cho', 'Suy giáp ở chó: tăng cân, rụng lông, lờ đờ.', 'Bổ sung hormone tuyến giáp suốt đời.', 'Xét nghiệm T4 sau vài tuần để chỉnh liều, sau đó kiểm tra định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('bc90c423-aad8-4a80-beb5-deaae2d23bab', 'Cushing (cường vỏ thượng thận) - chó', 'cushing (cuong vo thuong than) - cho', 'Cushing ở chó: uống nhiều, bụng phệ, rụng lông đối xứng.', 'Dùng thuốc ức chế sản xuất cortisol, theo dõi bằng test ACTH.', 'Tái khám kiểm tra cortisol theo lịch của bác sĩ; báo ngay nếu thú bỏ ăn, nôn hoặc lờ đờ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('dd736e23-a64e-4320-b489-c3a9fd3b4413', 'Viêm khớp, loạn sản xương hông - chó', 'viem khop, loan san xuong hong - cho', 'Viêm khớp, loạn sản xương hông ở chó: đi khập khiễng, khó đứng dậy.', 'Giảm đau, kháng viêm; kiểm soát cân nặng và vận động nhẹ nhàng.', 'Không dùng chung hai thuốc kháng viêm NSAID. Dùng lâu dài cần xét nghiệm gan thận định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('33831ab2-ddda-4acb-8400-dac697b80a41', 'Dị ứng da (Atopic) - chó', 'di ung da (atopic) - cho', 'Dị ứng da (viêm da cơ địa) ở chó: ngứa, liếm chân, da đỏ.', 'Giảm ngứa và viêm; tìm và hạn chế tác nhân gây dị ứng.', 'Bệnh mạn tính, cần kiểm soát lâu dài. Tái khám sau 2-4 tuần.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('5814867d-5c53-4d64-a2ee-8807fdd124e7', 'Nhiễm trùng tiết niệu - chó', 'nhiem trung tiet nieu - cho', 'Nhiễm trùng tiết niệu ở chó: tiểu rắt, tiểu ra máu.', 'Kháng sinh theo kết quả xét nghiệm nước tiểu, cho uống nhiều nước.', 'Tái khám xét nghiệm lại nước tiểu sau khi hết thuốc.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('3424b767-0c5f-4670-923b-cb0102537406', 'Viêm tử cung mủ (Pyometra) - chó', 'viem tu cung mu (pyometra) - cho', 'Viêm tử cung mủ ở chó cái: chảy mủ âm hộ, uống nhiều, sốt.', 'Cấp cứu: thường phải phẫu thuật cắt tử cung; kháng sinh và thuốc nội khoa trong trường hợp đặc biệt.', 'Bệnh nặng có thể nguy hiểm tính mạng: cần đưa đi khám ngay.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('aee3244c-84c3-4adc-90e3-701f1e330996', 'Giun sán đường ruột - chó', 'giun san duong ruot - cho', 'Giun sán đường ruột ở chó: bụng to, tiêu chảy, thấy giun trong phân.', 'Tẩy giun sán, vệ sinh nơi ở.', 'Tẩy lại sau 2-3 tuần và tẩy giun định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('e608de56-8dc6-4248-8b55-74dc947ce5bc', 'Bệnh van tim (MMVD) - chó', 'benh van tim (mmvd) - cho', 'Bệnh van tim (MMVD) ở chó: ho, khó thở, mệt khi vận động.', 'Dùng thuốc hỗ trợ tim và lợi tiểu theo giai đoạn bệnh; hạn chế vận động mạnh.', 'Bệnh mạn tính, dùng thuốc lâu dài. Theo dõi nhịp thở lúc nghỉ tại nhà; tái khám siêu âm tim định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0fea5874-25b5-4781-8c7a-7463ff6eef29', 'Suy thận mạn - mèo', 'suy than man - meo', 'Suy thận mạn ở mèo: uống nhiều, gầy, nôn, hôi miệng.', 'Kiểm soát huyết áp và protein niệu, truyền dịch khi cần, ăn thức ăn chuyên cho thận.', 'Bệnh mạn tính. Xét nghiệm thận định kỳ; luôn cho mèo uống nước đầy đủ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('9db36b5e-bc1c-4627-bc42-a2e3732b63b1', 'Cường giáp - mèo', 'cuong giap - meo', 'Cường giáp ở mèo: ăn nhiều nhưng gầy, hiếu động, nôn.', 'Dùng thuốc kháng giáp hoặc chuyển sang thức ăn chuyên biệt theo chỉ định.', 'Xét nghiệm T4, men gan và công thức máu định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('d0968a22-6034-459b-9c5f-6c11ab20a183', 'Tiểu đường - mèo', 'tieu duong - meo', 'Tiểu đường ở mèo: uống nhiều, tiểu nhiều, đi lệch chân sau.', 'Tiêm insulin đều đặn kết hợp chế độ ăn ít tinh bột.', 'Chủ nuôi cần học cách tiêm và nhận biết hạ đường huyết. Tái khám đo đường huyết định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('2aecb0f0-a44b-406e-b38a-279d76338fce', 'Hen suyễn - mèo', 'hen suyen - meo', 'Hen suyễn ở mèo: ho, thở khò khè, thở há miệng.', 'Giãn phế quản và kháng viêm đường hô hấp; hạn chế bụi, khói, cát vệ sinh nhiều bụi.', 'Thở há miệng là cấp cứu: đưa đi khám ngay.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('7d7f6126-7cf7-4c24-909c-1515173fd7b0', 'Toxoplasma - mèo', 'toxoplasma - meo', 'Toxoplasma ở mèo: sốt, viêm mắt, triệu chứng thần kinh.', 'Kháng sinh diệt ký sinh trùng; điều trị hỗ trợ.', 'Bệnh lây sang người, nhất là phụ nữ mang thai: vệ sinh kỹ khi chăm sóc, đeo găng khi dọn khay cát.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('8e2b378f-f1ba-47eb-8e1c-56e219c83bf1', 'Thiếu máu do Mycoplasma haemofelis - mèo', 'thieu mau do mycoplasma haemofelis - meo', 'Thiếu máu do Mycoplasma haemofelis ở mèo: lợi nhợt, yếu, sốt.', 'Kháng sinh kết hợp thuốc ức chế miễn dịch khi cần; truyền máu nếu thiếu máu nặng.', 'Xét nghiệm công thức máu để theo dõi. Cho mèo uống thuốc đủ liệu trình.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('ebc25209-4f60-4121-9075-7bd2b01dc407', 'Rận tai (Otodectes) - mèo', 'ran tai (otodectes) - meo', 'Rận tai ở mèo: gãi tai, ráy tai đen như bã cà phê.', 'Diệt ký sinh trùng; vệ sinh tai.', 'Điều trị cả các thú khác sống chung. Tái khám sau 2-4 tuần.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('f6dd45eb-aae1-4e8f-abb6-698740be80bb', 'Bọ chét - mèo', 'bo chet - meo', 'Bọ chét ở mèo: ngứa, cắn lưng, viêm da dị ứng do nước bọt bọ chét.', 'Diệt bọ chét trên thú và xử lý môi trường sống.', 'Điều trị tất cả thú trong nhà và vệ sinh ổ nằm.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('da949265-0d1a-457e-ac58-71300498bd4a', 'Búi lông - mèo', 'bui long - meo', 'Búi lông ở mèo: nôn ra lông, táo bón.', 'Thuốc nhuận tràng giúp thải lông; chải lông thường xuyên.', 'Đưa đi khám nếu mèo nôn nhiều, bỏ ăn hoặc không đi tiêu.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('7a25438f-a4fb-4338-ba33-67bc7b389178', 'Giardia - mèo', 'giardia - meo', 'Giardia ở mèo: tiêu chảy kéo dài, phân nhầy mùi hôi.', 'Diệt ký sinh trùng, vệ sinh khay cát và nơi ở.', 'Giặt ổ nằm và tắm cho mèo để tránh tái nhiễm. Tái khám xét nghiệm phân.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0a5bdcbf-8270-4562-8d43-7442faec386e', 'Thiếu vitamin A - chim cảnh', 'thieu vitamin a - chim canh', 'Thiếu vitamin A ở chim cảnh: nốt trắng trong miệng, chảy mũi.', 'Bổ sung vitamin A và điều chỉnh khẩu phần (rau củ, thức ăn viên).', 'Thừa vitamin A cũng gây ngộ độc: dùng đúng liều bác sĩ chỉ định.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('40faf255-d5d5-4ce8-bd6a-b25d8738b433', 'Nấm diều (Candida) - chim cảnh', 'nam dieu (candida) - chim canh', 'Nấm diều (Candida) ở chim cảnh: nôn, diều căng, mỏ có mảng trắng.', 'Thuốc kháng nấm; vệ sinh dụng cụ ăn uống.', 'Tái khám nếu chim tiếp tục nôn hoặc bỏ ăn.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('1df8341c-c66b-477a-ba80-2999cfc3ea2b', 'Megabacteria (Macrorhabdus) - chim cảnh', 'megabacteria (macrorhabdus) - chim canh', 'Megabacteria (Macrorhabdus) ở chim cảnh: gầy, nôn, phân có hạt nguyên.', 'Thuốc kháng nấm đường uống; hỗ trợ dinh dưỡng.', 'Chim yếu cần giữ ấm và theo dõi sát.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('37a7b3d6-4060-416a-bcc5-d7003b38ce50', 'CRD (Mycoplasma) - chim cảnh', 'crd (mycoplasma) - chim canh', 'CRD (Mycoplasma) ở chim cảnh: hắt hơi, sưng mắt, thở khò khè.', 'Kháng sinh; giữ ấm, thông thoáng, tránh gió lùa.', 'Cách ly chim bệnh với chim khỏe.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('15b8b537-3417-4872-be7a-4bb7ca23e201', 'Đậu chim (Avian Pox) - chim cảnh', 'dau chim (avian pox) - chim canh', 'Đậu chim (Avian Pox): nốt sần ở mỏ, chân, quanh mắt.', 'Không có thuốc đặc trị; sát trùng nốt và bổ sung vitamin A, chăm sóc hỗ trợ.', 'Bệnh lây giữa các con: cách ly chim bệnh. Có thể bội nhiễm, cần theo dõi.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('db5fe314-8d9d-4200-8235-60b1e3a4c569', 'Trùng roi (Trichomonas) - chim cảnh', 'trung roi (trichomonas) - chim canh', 'Trùng roi (Trichomonas) ở chim cảnh: nuốt khó, mảng vàng trong họng, chảy dãi.', 'Thuốc diệt trùng roi; vệ sinh nước uống và dụng cụ ăn.', 'Điều trị cả đàn nếu nuôi chung.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('2874c0a4-f9f9-49eb-9c96-793817b18bde', 'Nhiễm khuẩn E. coli, Salmonella - chim cảnh', 'nhiem khuan e. coli, salmonella - chim canh', 'Nhiễm khuẩn E. coli, Salmonella ở chim cảnh: tiêu chảy, phân xanh lỏng, xù lông.', 'Kháng sinh theo chỉ định; bù nước, giữ ấm, vệ sinh lồng.', 'Salmonella có thể lây sang người: rửa tay kỹ sau khi chăm sóc.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('19e09369-0894-472f-b982-b5da867398c0', 'Kẹt trứng - chim cảnh', 'ket trung - chim canh', 'Kẹt trứng ở chim cảnh: rặn liên tục, đứng dưới đáy lồng, bụng phình.', 'Sưởi ấm, bổ sung canxi; dùng thuốc co bóp tử cung khi bác sĩ xác định phù hợp.', 'Cấp cứu: để chim ở nơi ấm, yên tĩnh và đưa đi khám ngay. Không tự bóp bụng chim.', '00000000-0000-0000-0000-000000000000', '2026-11-11 17:26:21.940671+00', '2026-11-11 17:26:21.940671+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('8091f2dd-7b31-42b8-aba4-5ff08fe00471', 'Viêm dạ dày cấp - chó, mèo', 'viem da day cap - cho, meo', 'Viêm dạ dày cấp: nôn, bỏ ăn, đau bụng, liếm môi.', 'Giảm tiết acid, chống nôn; cho nhịn ăn ngắn rồi ăn lại thức ăn dễ tiêu theo chỉ định.', 'Tái khám nếu nôn kéo dài, nôn ra máu hoặc bỏ ăn quá 24 giờ.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('4845e7d9-74b7-4752-9787-31768866a52f', 'Loét dạ dày - chó, mèo', 'loet da day - cho, meo', 'Loét dạ dày: nôn ra máu, phân đen, đau vùng bụng trên.', 'Giảm tiết acid và bảo vệ niêm mạc dạ dày; tìm và loại bỏ nguyên nhân (thuốc kháng viêm, stress, bệnh nền).', 'Ngưng các thuốc kháng viêm NSAID hoặc corticoid nếu bác sĩ chỉ định. Nôn ra máu nhiều hoặc phân đen kéo dài cần khám ngay.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('b8420b2c-2316-421e-9797-dcd529762965', 'Dị vật đường tiêu hóa - chó, mèo', 'di vat duong tieu hoa - cho, meo', 'Đau bụng do dị vật đường tiêu hóa: nôn liên tục, đau bụng, không đi ngoài.', 'Nội soi hoặc phẫu thuật lấy dị vật; truyền dịch và giảm đau.', 'Cấp cứu: không tự gây nôn, không cho ăn uống khi chưa có chỉ định. Đưa đi khám ngay.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('a54b817b-9d3e-485f-ad3f-e961986c8b5f', 'Xoắn dạ dày (GDV) - chó', 'xoan da day (gdv) - cho', 'Xoắn dạ dày (GDV) ở chó: bụng chướng căng, nôn khan, bồn chồn.', 'Cấp cứu phẫu thuật; truyền dịch chống sốc và theo dõi nhịp tim.', 'Cấp cứu nguy hiểm tính mạng: đưa đi khám ngay, không chờ. Chó giống lớn, ngực sâu có nguy cơ cao.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('7167fd57-6c50-4504-882e-f08f8dd2af74', 'Viêm ruột cấp, tiêu chảy cấp - chó, mèo', 'viem ruot cap, tieu chay cap - cho, meo', 'Viêm ruột cấp, tiêu chảy cấp: tiêu chảy, đau quặn bụng, mất nước.', 'Bù nước, cầm tiêu chảy, bổ sung men vi sinh; cho ăn thức ăn dễ tiêu.', 'Tái khám nếu tiêu chảy ra máu, kéo dài quá 2-3 ngày hoặc thú lờ đờ, bỏ ăn.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('5c0d36aa-4fd6-4914-b728-5392e3f8f1bd', 'Viêm ruột mạn (IBD) - chó, mèo', 'viem ruot man (ibd) - cho, meo', 'Viêm ruột mạn (IBD): nôn và tiêu chảy kéo dài, sụt cân.', 'Ức chế viêm bằng corticoid; kết hợp thức ăn thủy phân (VD: Hill''s z/d) theo chỉ định.', 'Bệnh mạn tính, cần theo dõi lâu dài. Không tự ngừng corticoid đột ngột.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('a0dcb89f-f9d2-48c3-b2e8-32446b32b104', 'Trào ngược dạ dày thực quản - chó, mèo', 'trao nguoc da day thuc quan - cho, meo', 'Trào ngược dạ dày thực quản: ợ, nôn trớ, nuốt khó, ăn ít.', 'Giảm tiết acid và tăng nhu động dạ dày; chia nhỏ bữa ăn.', 'Tái khám nếu nôn trớ kéo dài hoặc thú sụt cân.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('87c93392-7965-4627-8163-c3e2e2a828f4', 'Khô mắt (KCS) - chó', 'kho mat (kcs) - cho', 'Khô mắt: ghèn đặc, giác mạc khô, mờ.', 'Kích thích tiết nước mắt bằng thuốc nhỏ mắt dùng lâu dài; bổ sung nước mắt nhân tạo.', 'Thường phải dùng lâu dài, không tự ngừng. Làm sạch ghèn trước khi nhỏ thuốc.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('bc25028d-fd76-4e41-9611-2309324f06de', 'Táo bón, phình đại tràng - mèo', 'tao bon, phinh dai trang - meo', 'Táo bón, phình đại tràng ở mèo: rặn lâu, phân khô cứng, đau bụng.', 'Thuốc nhuận tràng, thuốc tăng nhu động ruột; thụt tháo khi cần.', 'Cho mèo uống đủ nước. Tái khám nếu không đi tiêu quá 48 giờ, nôn hoặc bỏ ăn.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('d3b46082-ce35-4776-884d-c0614b7b99b3', 'Ngộ độc (socola, nho, chuột, thuốc người) - chó, mèo', 'ngo doc (socola, nho, chuot, thuoc nguoi) - cho, meo', 'Ngộ độc (socola, nho, thuốc chuột, thuốc người): nôn, run, co giật, đau bụng.', 'Cấp cứu: gây nôn khi còn kịp và phù hợp, than hoạt tính hấp phụ độc chất, truyền dịch hỗ trợ.', 'Cấp cứu: mang theo bao bì hoặc mẫu chất thú đã ăn. Không tự gây nôn tại nhà khi chưa hỏi bác sĩ.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('5eefee11-89c3-4be9-854f-0104c443a19c', 'Gan nhiễm mỡ - mèo', 'gan nhiem mo - meo', 'Gan nhiễm mỡ ở mèo: bỏ ăn nhiều ngày, vàng da, gầy.', 'Nuôi ăn bằng ống để cung cấp dinh dưỡng; kích thích ăn và hỗ trợ gan.', 'Mèo bỏ ăn quá 2-3 ngày cần đưa đi khám sớm. Tái khám xét nghiệm men gan.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('ccb0fb2f-eb92-4518-82ed-3b953850edca', 'Sỏi bàng quang - chó', 'soi bang quang - cho', 'Sỏi bàng quang ở chó: tiểu ra máu, tiểu rắt.', 'Thức ăn tan sỏi (VD: Hill''s c/d, s/d) hoặc phẫu thuật lấy sỏi; kháng sinh khi có nhiễm trùng.', 'Cho chó uống nhiều nước. Tái khám siêu âm hoặc X-quang sau điều trị.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('78083f7c-1d18-4453-bff5-e7802c47e496', 'Viêm da có mủ (Pyoderma) - chó', 'viem da co mu (pyoderma) - cho', 'Viêm da có mủ (Pyoderma) ở chó: mụn mủ, vảy, ngứa.', 'Kháng sinh đường uống kết hợp tắm bằng dầu tắm sát khuẩn.', 'Dùng đủ liệu trình kháng sinh. Tìm nguyên nhân nền (dị ứng, ký sinh trùng) để tránh tái phát.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('a5d8c964-b51a-4397-b000-a6069d9a7cb7', 'Viêm loét giác mạc - chó', 'viem loet giac mac - cho', 'Viêm loét giác mạc ở chó: nheo mắt, chảy nước mắt, mắt đục.', 'Nhỏ kháng sinh, nhỏ thuốc giãn đồng tử giảm đau; đeo vòng cổ chống liếm, không cho cào mắt.', 'Bệnh có thể nặng lên rất nhanh: tái khám đúng hẹn để kiểm tra vết loét.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('e80d9c14-92ed-4d24-b7be-f55cd28728f2', 'Động kinh - chó', 'dong kinh - cho', 'Động kinh ở chó: co giật từng cơn, sùi bọt mép.', 'Thuốc chống co giật dùng đều đặn lâu dài; ghi lại thời gian và tần suất mỗi cơn.', 'Không tự ngừng thuốc đột ngột. Cơn co giật kéo dài quá 5 phút là cấp cứu. Xét nghiệm nồng độ thuốc và men gan định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('c08d831c-5b82-4f3d-9d29-1d4847513101', 'Thoát vị đĩa đệm - chó', 'thoat vi dia dem - cho', 'Thoát vị đĩa đệm ở chó (Corgi, Dachshund...): đau lưng, run, yếu hoặc liệt chân sau.', 'Nghỉ ngơi trong chuồng hạn chế vận động; giảm đau, kháng viêm, giãn cơ; phẫu thuật nếu liệt nặng.', 'Không dùng chung Prednisolone và Meloxicam. Chân sau yếu hoặc liệt cần khám ngay.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('2f05c52a-c532-42d7-b3d5-fb23f2928d34', 'Bệnh cơ tim phì đại (HCM) - mèo', 'benh co tim phi dai (hcm) - meo', 'Bệnh cơ tim phì đại (HCM) ở mèo: thở nhanh, liệt chân sau đột ngột (do huyết khối).', 'Chống đông tiểu cầu phòng huyết khối, kiểm soát nhịp tim, lợi tiểu khi có dịch phổi.', 'Liệt chân sau đột ngột hoặc thở há miệng là cấp cứu. Siêu âm tim định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('30b955fb-c9a3-4eed-aac3-2cd473864b3c', 'Mụn cằm - mèo', 'mun cam - meo', 'Mụn cằm ở mèo: mụn đen hoặc mụn mủ ở cằm.', 'Vệ sinh sát khuẩn vùng cằm, bôi thuốc kháng khuẩn; đổi bát ăn sang inox hoặc sứ.', 'Rửa bát ăn thường xuyên. Tái khám nếu mụn mủ lan rộng hoặc sưng.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('381af826-8f34-4111-81e2-e4dd0311e1fd', 'Gout - chim cảnh', 'gout - chim canh', 'Gout ở chim cảnh: khớp chân sưng, có nốt trắng, đứng không vững.', 'Giảm acid uric, bù nước; giảm đạm trong khẩu phần.', 'Điều chỉnh khẩu phần ăn theo hướng dẫn của bác sĩ. Tái khám xét nghiệm acid uric.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('e3fc3eed-8a30-4bd3-844b-0e569a19726c', 'Thiếu canxi - chim cảnh', 'thieu canxi - chim canh', 'Thiếu canxi ở chim cảnh: run, co giật, trứng vỏ mềm.', 'Bổ sung canxi và vitamin D3; cho chim tắm nắng hoặc dùng đèn UVB.', 'Thừa vitamin D3 cũng gây ngộ độc: dùng đúng liều bác sĩ chỉ định.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('63a6fa2b-9edb-4d28-a6fb-dbadabe39430', 'Ngộ độc kim loại nặng (chì, kẽm) - chim cảnh', 'ngo doc kim loai nang (chi, kem) - chim canh', 'Ngộ độc kim loại nặng (chì, kẽm) ở chim cảnh: nôn, phân lẫn máu, co giật.', 'Thuốc thải kim loại nặng; điều trị hỗ trợ; tìm và loại bỏ nguồn kim loại.', 'Kiểm tra lồng, đồ chơi, dây kim loại mạ kẽm. Theo dõi chức năng gan, thận.', '00000000-0000-0000-0000-000000000000', '2026-11-12 03:15:17.237952+00', '2026-11-12 03:15:17.237952+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('983e4b96-6b6f-4000-a7a4-2d6d9bdd5284', 'Viêm kết mạc - chó, mèo', 'viem ket mac - cho, meo', 'Viêm kết mạc: mắt đỏ, nhiều ghèn, chảy nước mắt.', 'Làm sạch ghèn quanh mắt; nhỏ hoặc tra thuốc mắt kháng sinh theo chỉ định.', 'Không để thú dụi hoặc cào mắt. Tái khám nếu mắt đục, đau nhiều hoặc không đỡ sau vài ngày.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('70de44fa-9a73-4874-8548-9a2abd823367', 'Đục thủy tinh thể - sau mổ - chó, mèo', 'duc thuy tinh the - sau mo - cho, meo', 'Đục thủy tinh thể: mắt đục trắng, va vấp đồ vật. Chăm sóc sau phẫu thuật Phaco.', 'Chống viêm sau mổ bằng thuốc nhỏ mắt theo chỉ định.', 'Đeo vòng chống liếm, không để thú dụi mắt. Tái khám đúng hẹn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('ce7e55c6-f8e0-4f80-8a82-c50357eb15e8', 'Tăng nhãn áp (Glaucoma) - chó', 'tang nhan ap (glaucoma) - cho', 'Tăng nhãn áp: mắt đỏ, giãn đồng tử, đau mắt.', 'Hạ nhãn áp bằng thuốc nhỏ mắt; theo dõi nhãn áp định kỳ.', 'Cấp cứu mắt: tăng nhãn áp lâu có thể gây mù. Tái khám đo nhãn áp theo hẹn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('a642ef60-adef-4fbc-b845-6b2defe3025c', 'Viêm tuyến hậu môn - chó, mèo', 'viem tuyen hau mon - cho, meo', 'Viêm tuyến hậu môn: lết mông, liếm hậu môn, sưng.', 'Nặn tuyến hậu môn; kháng sinh và giảm đau kháng viêm.', 'Tái khám nếu sưng nóng, rò mủ hoặc thú đau khi đi ngoài.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('1f7a89ef-8f3f-488d-9406-6f0e9e4d3e92', 'Áp xe do cắn nhau - chó, mèo', 'ap xe do can nhau - cho, meo', 'Áp xe do cắn nhau: sưng nóng, có mủ, sốt.', 'Rạch dẫn lưu mủ, rửa vết thương; dùng kháng sinh.', 'Giữ vết thương sạch, không để thú liếm. Tái khám để thay băng và kiểm tra dẫn lưu.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('428fdd8b-7a1e-4f13-90d5-883d93386650', 'Say nóng (Heat stroke) - chó, mèo', 'say nong (heat stroke) - cho, meo', 'Say nóng: thở dốc, lưỡi đỏ thẫm, lả, nôn.', 'Cấp cứu: hạ nhiệt từ từ bằng nước thường, truyền dịch, thở oxy.', 'Cấp cứu: không dùng nước đá để làm mát. Đưa đi khám ngay.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('989f399f-25d6-4d62-9edc-95a6ab69d780', 'Viêm phổi do vi khuẩn - chó, mèo', 'viem phoi do vi khuan - cho, meo', 'Viêm phổi do vi khuẩn: ho, sốt, thở nhanh.', 'Kháng sinh, khí dung làm loãng đờm; nghỉ ngơi nơi thoáng mát, tránh vận động mạnh.', 'Tái khám nếu thở khó, tím tái hoặc bỏ ăn. Cho uống đủ liệu trình kháng sinh.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('372e75f4-2360-46c3-9ce6-cb161676753b', 'Vết thương, bỏng ngoài da - chó, mèo', 'vet thuong, bong ngoai da - cho, meo', 'Vết thương, bỏng ngoài da: da tổn thương, rỉ dịch.', 'Làm sạch vết thương, sát khuẩn, bôi thuốc tại chỗ và băng; kháng sinh khi nhiễm trùng.', 'Giữ vết thương sạch và khô, đeo vòng chống liếm. Tái khám nếu sưng đỏ, có mủ hoặc sốt.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('17dd4010-a86b-43ca-b24a-d748975b5e58', 'U tế bào mast - chó', 'u te bao mast - cho', 'U tế bào mast: khối u da, có thể đỏ và sưng lên.', 'Phẫu thuật cắt u; dùng thuốc kháng viêm, thuốc điều trị đích theo chỉ định.', 'Thuốc này do bác sĩ thú y chuyên khoa chỉ định và theo dõi xét nghiệm định kỳ. Không bóp hoặc chà xát khối u.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('b12e0702-0211-4102-8e81-d34e7fc97c94', 'Lymphoma - chó, mèo', 'lymphoma - cho, meo', 'Lymphoma: hạch to, sụt cân, mệt.', 'Hoá trị theo phác đồ CHOP kèm Prednisolone.', 'Thuốc này do bác sĩ thú y chuyên khoa chỉ định và theo dõi xét nghiệm định kỳ. Theo dõi công thức máu trước mỗi đợt hoá trị.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('ef7a8d5f-5fea-4fec-9c5c-2e52dcba155e', 'Giun phổi - chó, mèo', 'giun phoi - cho, meo', 'Giun phổi: ho mạn tính, khó thở.', 'Tẩy giun phổi; có thể lặp lại theo chỉ định.', 'Tái khám sau khi tẩy để kiểm tra lại; tẩy giun định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0c8d14d2-d2dc-4bbc-9596-3776ed273bfe', 'Thiếu máu tan huyết miễn dịch (IMHA) - chó, mèo', 'thieu mau tan huyet mien dich (imha) - cho, meo', 'Thiếu máu tan huyết miễn dịch: lợi nhợt, vàng da, nước tiểu sẫm.', 'Ức chế miễn dịch; theo dõi hồng cầu và chức năng gan, thận.', 'Thuốc này do bác sĩ thú y chuyên khoa chỉ định và theo dõi xét nghiệm định kỳ. Không tự ngừng thuốc.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('4f35a39c-373e-4183-b6a1-90002db57797', 'Giảm tiểu cầu miễn dịch (ITP) - chó, mèo', 'giam tieu cau mien dich (itp) - cho, meo', 'Giảm tiểu cầu miễn dịch: chấm xuất huyết, chảy máu cam.', 'Ức chế miễn dịch; theo dõi số lượng tiểu cầu.', 'Thuốc này do bác sĩ thú y chuyên khoa chỉ định và theo dõi xét nghiệm định kỳ. Hạn chế vận động mạnh, tránh va chạm khi tiểu cầu thấp.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('9be79550-f9e4-4181-b019-f4ef0aeb5ea1', 'Hạ đường huyết - chó, mèo con, giống nhỏ', 'ha duong huyet - cho, meo con, giong nho', 'Hạ đường huyết: run, lờ đờ, co giật.', 'Bổ sung đường: truyền dextrose hoặc bôi nướu; cho ăn sau khi tỉnh.', 'Cấp cứu nếu thú co giật hoặc lịm đi. Chia nhiều bữa ăn nhỏ trong ngày.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('337817c4-846f-4ef9-af9e-26f33e9861e6', 'Sản giật (mẹ sau sinh) - chó, mèo', 'san giat (me sau sinh) - cho, meo', 'Sản giật: run, thở gấp, co cứng cơ ở mẹ sau sinh.', 'Bổ sung canxi đường tĩnh mạch rồi duy trì bằng canxi đường uống; tạm tách con khỏi mẹ.', 'Cấp cứu: đưa đi khám ngay. Truyền canxi phải theo dõi nhịp tim.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0837efb6-cfc6-4e45-a701-9140e70734c9', 'Cầu trùng - chó, mèo con', 'cau trung - cho, meo con', 'Cầu trùng: tiêu chảy, có thể lẫn máu.', 'Diệt cầu trùng; bù nước; vệ sinh chuồng, ổ nằm.', 'Vệ sinh chuồng hằng ngày, tách thú bệnh. Tái khám nếu mất nước, bỏ ăn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('171dd94c-e5f7-407a-9314-3c4ac4a012a9', 'Hội chứng mũi ngắn - chó (Pug, Bulldog)', 'hoi chung mui ngan - cho (pug, bulldog)', 'Hội chứng mũi ngắn: ngáy, thở khò khè, dễ ngất khi nóng.', 'Giảm cân; phẫu thuật mở rộng mũi, cắt ngắn vòm họng khi cần; chống viêm.', 'Tránh nơi nóng và vận động mạnh. Giữ cân nặng hợp lý.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('363485c8-aafa-4d63-b51d-82a984564d7d', 'Xẹp khí quản - chó giống nhỏ', 'xep khi quan - cho giong nho', 'Xẹp khí quản: ho như tiếng ngỗng kêu.', 'Giảm ho, giãn phế quản, chống viêm; kiểm soát cân nặng, dùng dây ngực thay vòng cổ.', 'Dùng dây ngực thay vòng cổ. Tránh kích thích, nơi nóng hoặc bụi.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('5d986f78-a397-4274-8f22-c090ebbc8ae6', 'Đứt dây chằng chéo trước - chó', 'dut day chang cheo truoc - cho', 'Đứt dây chằng chéo trước: đột ngột khập khiễng chân sau.', 'Giảm đau, chống viêm; phẫu thuật ổn định khớp (TPLO) khi cần; hạn chế vận động.', 'Nghỉ ngơi, hạn chế chạy nhảy, leo cầu thang. Giữ cân nặng hợp lý.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('648086aa-12e2-4a57-8166-f2f096d640bc', 'Trật xương bánh chè - chó', 'trat xuong banh che - cho', 'Trật xương bánh chè: đi nhảy cóc, co chân sau.', 'Giảm đau, chống viêm, bổ sung glucosamine; phẫu thuật khi nặng.', 'Hạn chế nhảy, leo cầu thang. Giữ cân nặng hợp lý.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('76bc797d-f91e-4470-8cef-c9e884819384', 'Addison (suy vỏ thượng thận) - chó', 'addison (suy vo thuong than) - cho', 'Addison: nôn, yếu, có thể suy sụp đột ngột.', 'Thay thế hormone thượng thận; theo dõi điện giải định kỳ.', 'Suy sụp đột ngột là cấp cứu. Không tự ngừng thuốc. Xét nghiệm điện giải theo hẹn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('211799ef-5d3d-4159-9f34-d37dbc1eb849', 'Bệnh cơ tim giãn (DCM) - chó', 'benh co tim gian (dcm) - cho', 'Bệnh cơ tim giãn: mệt, ho, bụng chướng nước.', 'Tăng sức co bóp tim, lợi tiểu, giãn mạch; theo dõi siêu âm tim.', 'Hạn chế vận động mạnh; theo dõi nhịp thở lúc nghỉ. Tái khám định kỳ.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('c63bdae1-ade3-4d30-984f-cac8f0dde821', 'Bệnh tuyến tiền liệt - chó', 'benh tuyen tien liet - cho', 'Bệnh tuyến tiền liệt: tiểu khó, đi ngoài khó.', 'Giảm kích thước tuyến, kháng sinh khi nhiễm trùng; thiến để phòng tái phát.', 'Tái khám để kiểm tra lại kích thước tuyến. Thiến là cách phòng tái phát hiệu quả.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('84592358-d7a8-40e5-9498-f1cb73addf58', 'Nấm Malassezia - chó', 'nam malassezia - cho', 'Nấm Malassezia: da nhờn, mùi hôi, ngứa.', 'Tắm thuốc kháng nấm và dùng thuốc uống kháng nấm theo chỉ định.', 'Tắm đúng lịch, để dầu tắm đủ thời gian rồi xả sạch. Tái khám để đánh giá lại.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0e5784a7-a1cb-4716-ba57-61d0c79ba124', 'U hạt do liếm (Lick granuloma) - chó', 'u hat do liem (lick granuloma) - cho', 'U hạt do liếm: liếm một chỗ liên tục, vết loét dày.', 'Điều trị nhiễm trùng thứ phát, giảm hành vi liếm; tìm nguyên nhân (đau, dị ứng, stress).', 'Đeo vòng chống liếm. Tăng vận động và đồ chơi để giảm stress.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('9ae3e326-ee9c-447d-bfbf-8ed7dfa02711', 'Giãn thực quản (Megaesophagus) - chó', 'gian thuc quan (megaesophagus) - cho', 'Giãn thực quản: trớ thức ăn sau khi ăn, viêm phổi hít.', 'Cho ăn ở tư thế đứng (ghế Bailey); thuốc hỗ trợ nhu động.', 'Cho ăn ở tư thế đứng và giữ nguyên tư thế 10-15 phút sau ăn. Theo dõi dấu hiệu viêm phổi hít.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('c736bc03-df55-4a51-8043-080ee5afde45', 'Viêm miệng mạn tính (FCGS) - mèo', 'viem mieng man tinh (fcgs) - meo', 'Viêm miệng mạn tính: đau miệng nặng, chảy dãi, bỏ ăn.', 'Chống viêm, điều hoà miễn dịch; nhổ răng khi cần; chăm sóc răng miệng.', 'Tái khám nếu mèo bỏ ăn quá 24 giờ. Chăm sóc răng miệng theo hướng dẫn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('3703758a-6944-4afa-b208-0b45fbe91ccb', 'Tăng huyết áp - mèo', 'tang huyet ap - meo', 'Tăng huyết áp: mù đột ngột, đồng tử giãn.', 'Hạ huyết áp bằng thuốc; theo dõi huyết áp và tìm bệnh nền (thận, cường giáp).', 'Theo dõi huyết áp định kỳ. Mù đột ngột là cấp cứu.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('dd688cd6-d080-4b0f-9c86-86383f9a149b', 'Viêm đường mật (Cholangitis) - mèo', 'viem duong mat (cholangitis) - meo', 'Viêm đường mật: vàng da, sốt, bỏ ăn.', 'Hỗ trợ gan mật, kháng sinh và chống viêm theo chỉ định; dinh dưỡng hỗ trợ.', 'Tái khám nếu bỏ ăn quá 24 giờ. Mèo bỏ ăn có nguy cơ gan nhiễm mỡ.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('f63a3c0b-4fc3-4634-9d22-176404abbdfb', 'Viêm mũi mạn tính - mèo', 'viem mui man tinh - meo', 'Viêm mũi mạn tính: chảy mũi, hắt hơi kéo dài.', 'Khí dung nước muối, kháng sinh và chống viêm theo chỉ định; vệ sinh mũi.', 'Lau sạch dịch mũi. Tái khám nếu chảy mũi có máu hoặc bỏ ăn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('f33f4a0f-f835-4afc-8c44-faf80e436077', 'Rụng lông do liếm quá mức (stress) - mèo', 'rung long do liem qua muc (stress) - meo', 'Rụng lông do liếm quá mức: liếm trụi lông vùng bụng, đùi.', 'Giảm stress và làm phong phú môi trường; dùng thuốc ổn định tâm lý khi cần.', 'Cần loại trừ nguyên nhân khác (ngứa, ký sinh trùng, đau) trước khi dùng thuốc. Thêm đồ chơi, chỗ trèo, chỗ trốn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('3de74675-da6a-404a-b34e-acaa87f51791', 'Ung thư biểu mô vảy (mèo lông trắng)', 'ung thu bieu mo vay (meo long trang)', 'Ung thư biểu mô vảy: loét ở vành tai, mũi không lành.', 'Phẫu thuật cắt, xạ trị; giảm đau chống viêm.', 'Cho mèo lông trắng tránh nắng. Tái khám sớm khi có vết loét lâu lành.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('9e5f88c6-94dc-44e3-b339-10970d6acb0f', 'Phức hợp u hạt bạch cầu ái toan - mèo', 'phuc hop u hat bach cau ai toan - meo', 'Phức hợp u hạt bạch cầu ái toan: loét môi trên, mảng đỏ ngứa.', 'Chống viêm và ức chế miễn dịch; tìm nguyên nhân dị ứng.', 'Tìm và loại bỏ nguyên nhân dị ứng (bọ chét, thức ăn, môi trường).', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0dfa81df-052a-4da5-80ea-6974f7ff4769', 'Bartonella (bệnh mèo cào) - mèo', 'bartonella (benh meo cao) - meo', 'Bartonella: sốt, sưng hạch, thường không rõ triệu chứng.', 'Dùng kháng sinh kéo dài theo chỉ định.', 'Cần dùng đủ liệu trình kháng sinh. Bắt bọ chét định kỳ vì bọ chét lây bệnh.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('16ab3661-7a61-4b2b-ab8a-cdec7c15dee7', 'Polyp mũi họng - mèo (sau mổ)', 'polyp mui hong - meo (sau mo)', 'Polyp mũi họng: thở khò khè, nghiêng đầu, viêm tai.', 'Phẫu thuật lấy polyp; dùng corticoid ngắn ngày sau mổ để giảm tái phát.', 'Tái khám đúng hẹn; polyp có thể tái phát.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('d5507bf5-fdfe-490e-90da-6027ed633220', 'Viêm xoang - chim cảnh', 'viem xoang - chim canh', 'Viêm xoang: sưng quanh mắt, chảy mũi.', 'Kháng sinh, rửa xoang bằng nước muối.', 'Giữ chuồng sạch, thoáng, tránh gió lùa. Tái khám nếu sưng nhiều hoặc chim bỏ ăn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('0e55a78c-355d-4117-8b92-b9d0424d0e81', 'Giãn dạ dày tuyến (PDD, Bornavirus) - chim cảnh', 'gian da day tuyen (pdd, bornavirus) - chim canh', 'Giãn dạ dày tuyến: nôn, gầy, phân có hạt nguyên.', 'Chống viêm hỗ trợ và chăm sóc dinh dưỡng; bệnh khó chữa dứt điểm.', 'Cho ăn thức ăn mềm, dễ tiêu; tách chim bệnh khỏi đàn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('b599de0e-5f1c-40e9-94b3-c8078ed30815', 'Viêm gan bàn chân (Bumblefoot) - chim cảnh', 'viem gan ban chan (bumblefoot) - chim canh', 'Bumblefoot: gan bàn chân sưng đỏ, đóng vảy.', 'Làm sạch, kháng sinh, bôi thuốc tại chỗ; thay cầu đậu mềm.', 'Thay cầu đậu bằng loại mềm, đường kính phù hợp. Giữ chuồng khô sạch.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('48bff6a9-777f-4f83-ab3b-7c5dfe9b7720', 'Gãy chân, gãy cánh - chim cảnh', 'gay chan, gay canh - chim canh', 'Gãy chân, gãy cánh: không đứng được, cánh xệ.', 'Nẹp cố định; giảm đau chống viêm; hạn chế vận động.', 'Nhốt ở nơi yên tĩnh, thấp, không có cầu đậu cao.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('348c0acf-c49d-4681-9a03-dd439dabf9e0', 'Mạt mỏ (Knemidocoptes) - chim cảnh', 'mat mo (knemidocoptes) - chim canh', 'Mạt mỏ: mỏ và chân xốp như tổ ong.', 'Diệt mạt; vệ sinh chuồng và đồ vật.', 'Vệ sinh, khử trùng chuồng và đồ dùng. Tách chim bệnh khỏi đàn.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('d43a0e2a-dad1-4794-b317-dd7628f94ff7', 'Đẻ trứng liên tục - chim cảnh', 'de trung lien tuc - chim canh', 'Đẻ trứng liên tục: đẻ nhiều lứa, thiếu canxi.', 'Giảm kích thích đẻ: giảm thời gian chiếu sáng; dùng thuốc cấy hoặc tiêm ức chế hormone sinh sản.', 'Giảm thời gian chiếu sáng xuống khoảng 8-10 giờ/ngày, bỏ ổ đẻ. Bổ sung canxi theo chỉ định.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('92791680-5784-46a3-8689-610cce6edb7f', 'Gan nhiễm mỡ - chim cảnh', 'gan nhiem mo - chim canh', 'Gan nhiễm mỡ ở chim: béo, mỏ và móng mọc dài, khó thở.', 'Hỗ trợ gan; điều chỉnh khẩu phần, giảm hạt hướng dương.', 'Giảm hạt hướng dương, tăng rau củ; tăng vận động.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('7e880e85-c2e5-4559-8c9d-c938291cb0f9', 'Nhổ lông (Feather plucking) - chim cảnh', 'nho long (feather plucking) - chim canh', 'Nhổ lông: tự nhổ lông, da trụi.', 'Tìm nguyên nhân (đau, ngứa, stress); làm phong phú môi trường; dùng thuốc ổn định tâm lý khi cần.', 'Cần loại trừ bệnh da, ký sinh trùng trước khi dùng thuốc. Thêm đồ chơi, thời gian tương tác.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('f78e7981-48a2-408a-8a65-b28de0f15afe', 'Viêm kết mạc - chim cảnh', 'viem ket mac - chim canh', 'Viêm kết mạc ở chim: mắt sưng, nhắm mắt, chảy nước.', 'Nhỏ thuốc mắt kháng sinh; kháng sinh toàn thân khi nhiễm trùng hô hấp kèm theo.', 'Giữ chuồng sạch, tránh bụi và gió lùa. Tái khám nếu mắt sưng nhiều hoặc đục.', '00000000-0000-0000-0000-000000000000', '2026-11-13 10:33:53.72185+00', '2026-11-13 10:33:53.72185+00');
INSERT INTO public.prescription_templates (id, name, search_name, diagnosis, treatment, notes, created_by, created_at, updated_at) VALUES ('a1f97a21-144a-4292-8038-202308ae62de', 'viêm da', 'viem da', 'nổi đỏ', 'sức thuốc', 'vệ sinh cẩn thận', '349112bd-aa44-4beb-8339-16376986a41a', '2026-11-14 03:47:29.850899+00', '2026-11-14 03:47:29.850906+00');
